def min_essays(n, r, avg, exams):
    current_sum = sum(a for a, _ in exams)
    current_avg = current_sum / n
    required_sum = avg * n
    essays = 0

    if current_avg >= avg:
        return 0

    for grade, cost in exams:
        while grade < r and current_sum < required_sum:
            current_sum += 1
            essays += cost
            current_avg = current_sum / n
            if current_avg >= avg:
                return essays

    return -1  # If it's impossible to reach the required average

def main():
    n, r, avg = map(int, input().split())
    exams = [tuple(map(int, input().split())) for _ in range(n)]
    result = min_essays(n, r, avg, exams)
    print(result)

if __name__ == "__main__":
    main()
